    checksum: "a8391d2ae9ca63e7beea35e04ea0ffe928696dd8758a3fe82a2c7d5f8ea349af",
    sql: "-- Eventos: cru (auditoria + replay) e normalizado (§3.2).\n-- Ambas as tabelas são particionadas por dia. A limpeza é DROP PARTITION,\n-- que é O(1) e não gera VACUUM pesado (§10.2).\n--\n-- Regra do Postgres: numa tabela particionada, toda chave primária ou índice\n-- único PRECISA conter a coluna de partição. Por isso as PKs são compostas.\n\n-- Cru: tudo que chega, sem processar. Retenção 7 dias (§14.1).\nCREATE TABLE IF NOT EXISTS events_raw (\n  id            bigint GENERATED BY DEFAULT AS IDENTITY,\n  source_id     uuid REFERENCES sources(id) ON DELETE SET NULL,\n  received_at   timestamptz NOT NULL DEFAULT now(),\n  headers       jsonb,\n  payload       jsonb NOT NULL,\n  -- sha256(source_id + corpo). Plataformas fazem retry com frequência (§4.3).\n  dedupe_hash   text,\n  signature_ok  boolean,\n  processed_at  timestamptz,\n  error         text,\n  PRIMARY KEY (id, received_at)\n) PARTITION BY RANGE (received_at);\n\n-- A deduplicação consulta as últimas 24h por hash (§4.3).\nCREATE INDEX IF NOT EXISTS events_raw_dedupe_idx\n  ON events_raw (dedupe_hash, received_at DESC) WHERE dedupe_hash IS NOT NULL;\n-- Fila de normalização: o que ainda não foi processado.\nCREATE INDEX IF NOT EXISTS events_raw_pending_idx\n  ON events_raw (received_at) WHERE processed_at IS NULL;\nCREATE INDEX IF NOT EXISTS events_raw_source_idx\n  ON events_raw (source_id, received_at DESC);\n\n-- Normalizado: é sobre isto que os fluxos disparam. Retenção 30 dias.\nCREATE TABLE IF NOT EXISTS events (\n  id           bigint GENERATED BY DEFAULT AS IDENTITY,\n  org_id       uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  source_id    uuid REFERENCES sources(id) ON DELETE SET NULL,\n  -- evento canônico (§4.1)\n  type         text NOT NULL,\n  -- id do pedido/usuário na origem\n  external_id  text,\n  contact_id   uuid REFERENCES contacts(id) ON DELETE SET NULL,\n  occurred_at  timestamptz NOT NULL DEFAULT now(),\n  -- valores normalizados que alimentam as variáveis das mensagens (§6.3)\n  data         jsonb NOT NULL DEFAULT '{}'::jsonb,\n  raw_id       bigint,\n  PRIMARY KEY (id, occurred_at)\n) PARTITION BY RANGE (occurred_at);\n\nCREATE INDEX IF NOT EXISTS events_org_type_idx\n  ON events (org_id, type, occurred_at DESC);\nCREATE INDEX IF NOT EXISTS events_contact_idx\n  ON events (contact_id, occurred_at DESC);\n-- Impede que o mesmo evento da mesma origem entre duas vezes.\nCREATE UNIQUE INDEX IF NOT EXISTS events_source_type_external_uq\n  ON events (source_id, type, external_id, occurred_at);\n-- Suporte a §4.4: dado um order.created, houve order.paid com o mesmo external_id?\nCREATE INDEX IF NOT EXISTS events_org_external_idx\n  ON events (org_id, external_id, occurred_at DESC) WHERE external_id IS NOT NULL;\n",
